    aS2 += Math.sin(d2*f*1.3-t*sp*0.8+0.7)*w; iS2 += Math.cos(d2*f*0.5+t*sp*0.4-1.2)*w;
    nw += w;
  }
  const act=aS/nw, inh=iS/nw, act2=aS2/nw, inh2=iS2/nw;
  const bg = (Math.sin(fx*0.04+fy*0.025+t*0.8)+Math.sin(fx*0.03-fy*0.04+t*1.1)+Math.sin(fx*0.07+fy*0.05-t*0.6)+Math.cos(fx*0.05+fy*0.08+t*0.9))/4 + Math.sin((fx+fy)*0.12+t*2.5)*0.15 + Math.sin((fx-fy)*0.1-t*2)*0.15;
